"""Compile Sprig AST nodes to standalone Python source, without a VM or eval."""
from __future__ import annotations

import ast as python_ast
import math
from pathlib import Path

from . import ast_nodes as ast
from .semantics import SemanticAnalyzer


# Included in every generated file because it contains the shared runtime.
_RUNTIME_LICENSE = """MIT License

Copyright (c) 2026 Sprig contributors

Permission is hereby granted, free of charge, to any person obtaining a copy
of this software and associated documentation files (the "Software"), to deal
in the Software without restriction, including without limitation the rights
to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
copies of the Software, and to permit persons to whom the Software is
furnished to do so, subject to the following conditions:

The above copyright notice and this permission notice shall be included in all
copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
SOFTWARE.
"""


def _runtime_source() -> str:
    # Embed the actual shared implementation, rather than maintaining a second
    # copy of Sprig's arithmetic, built-ins, environments and diagnostics.
    chunks = []
    for name in ("errors.py", "runtime.py", "python_runtime.py"):
        source = Path(__file__).with_name(name).read_text(encoding="utf-8")
        excluded: set[int] = set()
        for node in python_ast.parse(source).body:
            if isinstance(node, python_ast.ImportFrom) and (node.level or node.module == "__future__"):
                excluded.update(range(node.lineno, node.end_lineno + 1))
        chunks.append("".join(line for number, line in enumerate(source.splitlines(keepends=True), 1) if number not in excluded))
    return "\n\n".join(chunks)


class PythonCompiler:
    def compile(self, program: ast.Program, source: str = "", filename: str = "<source>") -> str:
        SemanticAnalyzer().check(program)
        self.lines: list[str] = []
        self.counter = 0
        self._line(0, "def main(output=print):")
        self._line(1, "_env = make_globals(output)")
        self._line(1, "try:")
        self._line(2, "pass")
        self._statements(program, "_env", 2)
        self._line(1, "except SprigError as error:")
        self._line(2, "raise enrich_error(error, _SPRIG_SOURCE, _SPRIG_FILENAME) from None")
        self._line(0, "")
        self._line(0, 'if __name__ == "__main__":')
        self._line(1, "import sys")
        self._line(1, "try:")
        self._line(2, "main()")
        self._line(1, "except SprigError as error:")
        self._line(2, "print(error, file=sys.stderr)")
        self._line(2, "raise SystemExit(1)")
        header = (
            "# Generated by Sprig's Python compiler. Requires Python 3.9+.\n"
            "# Standalone runtime; Sprig source below is retained only for diagnostics.\n"
            "from __future__ import annotations\n\n"
        )
        header += "\n".join("# " + line if line else "#" for line in _RUNTIME_LICENSE.splitlines()) + "\n\n"
        metadata = f"\n\n_SPRIG_SOURCE = {source!r}\n_SPRIG_FILENAME = {filename!r}\n\n"
        return header + _runtime_source() + metadata + "\n".join(self.lines) + "\n"

    def _name(self, prefix: str) -> str:
        self.counter += 1
        return f"_sprig_{prefix}_{self.counter}"

    def _line(self, indent: int, text: str) -> None:
        self.lines.append("    " * indent + text)

    def _statements(self, statements: tuple[ast.Stmt, ...], env: str, indent: int) -> None:
        for statement in statements:
            self._line(indent, f"# Sprig line {statement.line}")
            self._statement(statement, env, indent)

    def _block(self, block: ast.BlockStmt, parent: str, indent: int) -> None:
        env = self._name("scope")
        self._line(indent, f"{env} = Environment({parent})")
        self._statements(block.statements, env, indent)

    def _statement(self, node: ast.Stmt, env: str, indent: int) -> None:
        if isinstance(node, ast.ExpressionStmt):
            self._line(indent, self._expression(node.expression, env))
        elif isinstance(node, ast.LetStmt):
            self._line(indent, f"{env}.define({node.name!r}, {self._expression(node.initializer, env)})")
        elif isinstance(node, ast.BlockStmt):
            self._block(node, env, indent)
        elif isinstance(node, ast.IfStmt):
            self._line(indent, f"if {self._expression(node.condition, env)}:")
            self._block(node.then_branch, env, indent + 1)
            if node.else_branch is not None:
                self._line(indent, "else:")
                self._statement(node.else_branch, env, indent + 1)
        elif isinstance(node, ast.WhileStmt):
            self._line(indent, f"while {self._expression(node.condition, env)}:")
            self._block(node.body, env, indent + 1)
        elif isinstance(node, ast.ForStmt):
            item, scope = self._name("item"), self._name("scope")
            iterable = self._at(node, "_sp_iter", self._expression(node.iterable, env))
            self._line(indent, f"for {item} in {iterable}:")
            self._line(indent + 1, f"{scope} = Environment({env})")
            self._line(indent + 1, f"{scope}.define({node.name!r}, {item})")
            self._statements(node.body.statements, scope, indent + 1)
        elif isinstance(node, ast.FunctionStmt):
            function, scope = self._name("fn"), self._name("scope")
            self._line(indent, f"def {function}(_closure, _args):")
            self._line(indent + 1, f"{scope} = Environment(_closure)")
            for index, name in enumerate(node.parameters):
                self._line(indent + 1, f"{scope}.define({name!r}, _args[{index}])")
            self._statements(node.body.statements, scope, indent + 1)
            self._line(indent + 1, "return None")
            self._line(indent, f"{env}.define({node.name!r}, CompiledFunction({node.name!r}, {node.parameters!r}, {function}, {env}))")
        elif isinstance(node, ast.ReturnStmt):
            self._line(indent, f"return {self._expression(node.value, env)}")
        else:
            raise AssertionError(f"unhandled statement {type(node).__name__}")

    @staticmethod
    def _at(node: ast.Node, operation: str, *args: str) -> str:
        return f"_sp_at({node.line}, {node.column}, {operation}, {', '.join(args)})"

    def _expression(self, node: ast.Expr, env: str) -> str:
        if isinstance(node, ast.Literal):
            if isinstance(node.value, float) and not math.isfinite(node.value):
                return f"float({str(node.value)!r})"
            return repr(node.value)
        if isinstance(node, ast.Variable):
            return f"{env}.get({node.name!r}, {node.line}, {node.column})"
        if isinstance(node, ast.Unary):
            return self._at(node, "unary_operation", repr(node.operator), self._expression(node.operand, env))
        if isinstance(node, ast.Binary):
            return self._at(node, "binary_operation", repr(node.operator), self._expression(node.left, env), self._expression(node.right, env))
        if isinstance(node, ast.Logical):
            return f"({self._expression(node.left, env)} {node.operator} {self._expression(node.right, env)})"
        if isinstance(node, ast.Assignment):
            value = self._expression(node.value, env)
            if isinstance(node.target, ast.Variable):
                return f"_sp_assign({env}, {node.target.name!r}, {value}, {node.line}, {node.column})"
            if isinstance(node.target, ast.Index):
                return self._at(node, "set_index", self._expression(node.target.collection, env), self._expression(node.target.index, env), value)
        if isinstance(node, ast.Call):
            arguments = "[" + ", ".join(self._expression(arg, env) for arg in node.arguments) + "]"
            return self._at(node, "_sp_call", self._expression(node.callee, env), arguments)
        if isinstance(node, ast.ListLiteral):
            return "[" + ", ".join(self._expression(element, env) for element in node.elements) + "]"
        if isinstance(node, ast.Index):
            return self._at(node, "get_index", self._expression(node.collection, env), self._expression(node.index, env))
        raise AssertionError(f"unhandled expression {type(node).__name__}")
